sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //Get the selected device type and quantity from RITM variables
    var deviceType = current.variables.device_type;
    var deviceQuantity = current.variables.gdr_quantity;
    gs.info(deviceQuantity + "test" + deviceType);
    //Create a GlideRecord object for Device Inventory Storage table
    var deviceInventoryGr = new GlideRecord('x_1459741_device_0_device_inventory_storage');
    //Query the Device Inventory Storage custom table for the selected device
    deviceInventoryGr.addQuery('sys_id', deviceType);
    deviceInventoryGr.query();
    gs.info("rowcouny" + deviceInventoryGr.getRowCount());
    //For new RITM creation (insert operation):
    if (deviceInventoryGr.next()) {
        //Get current device count from inventory

        var currentCount = deviceInventoryGr.getValue('u_total_quantity');
        //If sufficient inventory exists:
        if (currentCount >= deviceQuantity) {
            //Decrease the device count by requested quantity
            deviceInventoryGr.u_total_quantity = Number(currentCount) + deviceQuantity;
            //If RITM state is work in progress:- Increase the device_in_progress count
            var inProgressCount = deviceInventoryGr.u_device_in_progress;
            deviceInventoryGr.u_device_in_progress = inProgressCount - deviceQuantity;
            //Update the device inventory record
            deviceInventoryGr.update();
        }

    }

})(current, previous);
